mapper.insert:
INSERT INTO t_code (
    code_id, p_code_id, code_nm, code_desc, sort_no, use_yn,
    reg_id, upd_id, reg_dt, upd_dt, reg_ip, upd_ip
) VALUES (
    #{rowId}, #{pCodeId}, #{codeNm}, #{codeDesc},
    COALESCE(NULLIF(#{sortNo}, '')::integer,
        (SELECT COALESCE(MAX(sort_no), 0) + 1 FROM t_code WHERE p_code_id = #{pCodeId} AND use_yn = 'Y')), 'Y',
    #{regId}, #{updId}, NOW(), NOW(), #{regIp}, #{updIp}
)

mapper.update:
